import React from 'react';
import { Globe, MessageCircle } from 'lucide-react';

const Languages = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle form submission here
    console.log('Form submitted:', formData);
    // Reset form
    setFormData({ name: '', email: '', message: '' });
  };

  const languages = [
    {
      name: "English",
      level: "Fluent",
      proficiency: 95,
      description: "Professional working proficiency with excellent written and verbal communication skills.",
      flag: "🇺🇸",
      color: "from-blue-500 to-blue-600"
    },
    {
      name: "Amharic",
      level: "Native",
      proficiency: 100,
      description: "Native speaker with complete fluency in all aspects of the language.",
      flag: "🇪🇹",
      color: "from-green-500 to-green-600"
    }
  ];

  const communicationSkills = [
    {
      skill: "Technical Documentation",
      description: "Creating clear, comprehensive technical documentation and user guides",
      icon: "📝"
    },
    {
      skill: "Cross-Cultural Communication",
      description: "Effective communication across diverse cultural and professional contexts",
      icon: "🌍"
    },
    {
      skill: "Presentation Skills",
      description: "Delivering engaging presentations to technical and non-technical audiences",
      icon: "🎯"
    },
    {
      skill: "Team Collaboration",
      description: "Facilitating productive discussions and collaborative problem-solving",
      icon: "🤝"
    }
  ];

  return (
    <section className="section-padding bg-gray-50">
      <div className="container-max max-w-7xl mx-auto">
        <div className="text-center mb-16">
          <h2 className="text-4xl md:text-5xl font-bold text-gray-900 mb-4 font-poppins">
            Languages & Communication
          </h2>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">
            Bridging cultures and ideas through effective multilingual communication
          </p>
        </div>

        {/* Languages */}
        <div className="mb-16">
          <h3 className="text-2xl font-bold text-gray-900 mb-8 text-center font-poppins">
            Language Proficiency
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-4xl mx-auto">
            {languages.map((lang, index) => (
              <div 
                key={index}
                className="group bg-white rounded-2xl p-8 shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-gray-100"
              >
                {/* Header */}
                <div className="flex items-center gap-4 mb-6">
                  <div className={`w-16 h-16 rounded-xl bg-gradient-to-r ${lang.color} flex items-center justify-center text-2xl group-hover:scale-110 transition-transform duration-300`}>
                    {lang.flag}
                  </div>
                  <div className="flex-1">
                    <h4 className="text-2xl font-bold text-gray-900 mb-1 font-poppins">
                      {lang.name}
                    </h4>
                    <span className={`inline-block px-3 py-1 rounded-full text-sm font-medium text-white bg-gradient-to-r ${lang.color}`}>
                      {lang.level}
                    </span>
                  </div>
                </div>

                {/* Description */}
                <p className="text-gray-700 mb-6 leading-relaxed">
                  {lang.description}
                </p>

                {/* Proficiency Bar */}
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <span className="text-sm font-medium text-gray-700">Proficiency</span>
                    <span className="text-sm font-bold text-gray-900">{lang.proficiency}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-3">
                    <div 
                      className={`h-3 rounded-full bg-gradient-to-r ${lang.color} transition-all duration-1000 ease-out`}
                      style={{ width: `${lang.proficiency}%` }}
                    ></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Communication Skills */}
        <div>
          <h3 className="text-2xl font-bold text-gray-900 mb-8 text-center font-poppins">
            Communication Skills
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {communicationSkills.map((skill, index) => (
              <div 
                key={index}
                className="group bg-white rounded-xl p-6 shadow-lg hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border border-gray-100"
              >
                <div className="flex items-start gap-4">
                  <div className="w-12 h-12 rounded-lg bg-gradient-to-r from-accent-500 to-accent-600 flex items-center justify-center text-xl group-hover:scale-110 transition-transform duration-300">
                    {skill.icon}
                  </div>
                  <div className="flex-1">
                    <h4 className="text-lg font-bold text-gray-900 mb-2 font-poppins group-hover:text-primary-600 transition-colors duration-200">
                      {skill.skill}
                    </h4>
                    <p className="text-gray-700 text-sm leading-relaxed">
                      {skill.description}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Contact Form */}
        <div className="mt-16">
          <div className="bg-gradient-to-br from-primary-50 to-accent-50 rounded-3xl p-8 md:p-12 border border-primary-100 relative overflow-hidden">
            {/* Background decoration */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-br from-primary-200 to-accent-200 rounded-full -translate-y-16 translate-x-16 opacity-30"></div>
            <div className="absolute bottom-0 left-0 w-24 h-24 bg-gradient-to-br from-accent-200 to-primary-200 rounded-full translate-y-12 -translate-x-12 opacity-30"></div>

            <div className="relative z-10 max-w-2xl mx-auto">
              <div className="text-center mb-8">
                <div className="w-16 h-16 mx-auto mb-6 rounded-2xl bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center text-white">
                  <Send size={32} />
                </div>
                <h3 className="text-2xl font-bold text-gray-900 mb-4 font-poppins">
                  Get In Touch
                </h3>
                <p className="text-gray-700 leading-relaxed">
                  Have a project in mind or want to collaborate? I'd love to hear from you. 
                  Send me a message and let's create something amazing together.
                </p>
              </div>

              <form onSubmit={handleSubmit} className="space-y-6">
                {/* Name Field */}
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                    <User size={20} className="text-gray-400" />
                  </div>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    placeholder="Your Name"
                    required
                    className="w-full pl-12 pr-4 py-4 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200 text-gray-900 placeholder-gray-500"
                  />
                </div>

                {/* Email Field */}
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                    <Mail size={20} className="text-gray-400" />
                  </div>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    placeholder="Your Email"
                    required
                    className="w-full pl-12 pr-4 py-4 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200 text-gray-900 placeholder-gray-500"
                  />
                </div>

                {/* Message Field */}
                <div className="relative">
                  <div className="absolute top-4 left-0 pl-4 pointer-events-none">
                    <MessageCircle size={20} className="text-gray-400" />
                  </div>
                  <textarea
                    name="message"
                    value={formData.message}
                    onChange={handleInputChange}
                    placeholder="Your Message"
                    rows={5}
                    required
                    className="w-full pl-12 pr-4 py-4 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200 text-gray-900 placeholder-gray-500 resize-none"
                  />
                </div>

                {/* Submit Button */}
                <button
                  type="submit"
                  className="w-full bg-gradient-to-r from-primary-500 to-accent-500 text-white py-4 px-6 rounded-xl font-semibold hover:from-primary-600 hover:to-accent-600 transform hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl flex items-center justify-center gap-2"
                >
                  <Send size={20} />
                  Contact Me
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Languages;
